410:   template < GUM_Numeric GUM_SCALAR >
411:   DAG DoCalculus< GUM_SCALAR >::_removeInIntoDoing_outOfKnowing_(const DAG&     dag,
412:                                                                  const NodeSet& doing,
413:                                                                  const NodeSet& knowing) {
414:     DAG g = dag;   // copy
415:     for (auto x: doing) {
416:       auto ps = g.parents(x);
417:       for (auto p: ps)
418:         g.eraseArc(Arc(p, x));
419:     }
420:     for (auto z: knowing) {
421:       auto ch = g.children(z);
422:       for (auto c: ch)
423:         g.eraseArc(Arc(z, c));
424:     }
425:     return g;

