462:   template < GUM_Numeric GUM_SCALAR >
463:   typename DoCalculus< GUM_SCALAR >::FormulaPtr
464:       DoCalculus< GUM_SCALAR >::doCalculusWithObservation(const NodeSet& on,
465:                                                           const NodeSet& doing,
466:                                                           const NodeSet& knowing) const {
467:     // IDC reduction: try to promote any Z∈knowing to doing if Z ⟂ on | doing ∪ (knowing\{Z})
468:     // in the graph where incoming into doing and outgoing from knowing are removed.
469:     if (!knowing.empty()) {
470:       DAG gmod = _removeInIntoDoing_outOfKnowing_(_cm.causalDAG(), doing, knowing);
471: 
472:       for (auto z: knowing) {
473:         NodeSet Zi;
474:         Zi.insert(z);
475:         NodeSet Kminus = knowing - Zi;
476:         if (Separation::isDSeparated(gmod, Zi, on, doing + Kminus)) {
477:           // recurse with z moved to doing
478:           NodeSet doing2   = doing + Zi;
479:           NodeSet knowing2 = Kminus;
480:           return doCalculusWithObservation(on, doing2, knowing2);
481:         }
482:       }
483:     }
484: 
485:     // Fallback: ratio P(on ∪ knowing | do(doing)) / P(knowing | do(doing))
486:     NameList Yw, W;
487:     for (auto y: on)
488:       Yw.push_back(_cm.nameFromId(y));
489:     for (auto w: knowing)
490:       W.push_back(_cm.nameFromId(w));
491: 
492:     NameList Xn;
493:     for (auto x: doing)
494:       Xn.push_back(_cm.nameFromId(x));
495: 
496:     // numerator: ID on Y ∪ W ; denominator: ID on W (if W empty, denominator is 1)
497:     NodeSet onUkn = on + knowing;
498: 
499:     auto num = identifyingIntervention(onUkn, doing);
500:     if (knowing.empty()) {
501:       // P(Y|do(X)) when knowing is empty: just return numerator
502:       return num;
503:     }
504:     auto den = identifyingIntervention(knowing, doing);
505:     return std::make_unique< ASTdiv< GUM_SCALAR > >(std::move(num), std::move(den));
506:   }
