508:   template < GUM_Numeric GUM_SCALAR >
509:   typename DoCalculus< GUM_SCALAR >::FormulaPtr
510:       DoCalculus< GUM_SCALAR >::doCalculusWithObservation(const NameList& on,
511:                                                           const NameList& doing,
512:                                                           const NameList& knowing) const {
513:     NodeSet ON, DO, KN;
514:     for (const auto& s: on)
515:       ON.insert(_cm.idFromName(s));
516:     for (const auto& s: doing)
517:       DO.insert(_cm.idFromName(s));
518:     for (const auto& s: knowing)
519:       KN.insert(_cm.idFromName(s));
520:     return doCalculusWithObservation(ON, DO, KN);

527:   template < GUM_Numeric GUM_SCALAR >
528:   typename DoCalculus< GUM_SCALAR >::FormulaPtr
529:       DoCalculus< GUM_SCALAR >::_ID_(const CausalModel< GUM_SCALAR >&         cm,
530:                                      const NodeSet&                           Y,
531:                                      const NodeSet&                           X,
532:                                      std::unique_ptr< ASTtree< GUM_SCALAR > > P) const {
533:     const NodeSet lat = cm.latentVariablesIds();
534:     const NodeSet V   = cm.causalDAG().nodes().asNodeSet() - lat;
535: 
536:     // --- 1) if X is empty ---
537:     if (X.empty()) {
538:       if (!P) {
539:         // return P(Y)
540:         Set< std::string > Yn;
541:         for (auto y: Y)
542:           Yn.insert(cm.nameFromId(y));
543:         return std::make_unique< ASTjointProba< GUM_SCALAR > >(Yn);
544:       }
545:       // return sum_{V\Y} P
546:       NodeSet Vy = V - Y;
547:       if (Vy.empty()) return std::move(P);
548:       std::vector< std::string > tosum;
549:       tosum.reserve(Vy.size());
550:       for (auto v: Vy)
551:         tosum.push_back(cm.nameFromId(v));
552:       return std::make_unique< ASTsum< GUM_SCALAR > >(tosum, std::move(P));
553:     }
554: 
555:     // --- 2) restrict to ancestors of Y in G ---
556:     {
557:       DAG     g = cm.causalDAG();
558:       NodeSet A = _ancestorsIn_(g, Y);
559:       A += Y;
560:       // Only observed ancestors (V is observed-only)
561:       NodeSet Aobs = A - lat;
562:       if (Aobs.size() != V.size()) {
563:         // sum out V \ Aobs from P if present, recurse on induced submodel G[Aobs]
564:         if (P) {
565:           NodeSet VminusA = V - Aobs;
566:           if (!VminusA.empty()) {
567:             std::vector< std::string > tosum;
568:             tosum.reserve(VminusA.size());
569:             for (auto v: VminusA)
570:               tosum.push_back(cm.nameFromId(v));
571:             P = std::make_unique< ASTsum< GUM_SCALAR > >(tosum, std::move(P));
572:           }
573:         }
574:         auto    sub = cm.inducedCausalSubModel(cm, Aobs);
575:         NodeSet XA  = X * Aobs;
576:         return _ID_(sub, Y, XA, std::move(P));
577:       }
578:     }
579: 
580: 
581:     // --- 3) W := (V\X) \ An_{G_{\overline X}}(Y); if non-empty, move W to X and recurse ---
582:     {
583:       DAG     gXbar = _removeIncomingInto_(cm.causalDAG(), X);
584:       NodeSet AnY   = _ancestorsIn_(gXbar, Y);
585:       AnY += Y;
586:       NodeSet W = (V - X) - AnY;
587:       if (!W.empty()) { return _ID_(cm, Y, X + W, std::move(P)); }
588:     }
589: 
590:     // --- 4) c-decompose G[V\X]; if >1 component, multiply and sum ---
591:     {
592:       auto gvx   = cm.inducedCausalSubModel(cm, V - X);
593:       auto icomp = _cDecompositionOn_(gvx);
594: 
595:       if (icomp.size() > 1) {
596:         // t = Π_i ID(S_i, V \ S_i)
597:         std::unique_ptr< ASTtree< GUM_SCALAR > > t;
598:         for (size_t i = 0; i < icomp.size(); ++i) {
599:           NodeSet  Si = icomp[i];
600:           NameList Sn;
601:           for (auto s: Si)
602:             Sn.push_back(cm.nameFromId(s));
603: 
604:           std::unique_ptr< ASTtree< GUM_SCALAR > > Pcopy
605:               = P ? std::unique_ptr< ASTtree< GUM_SCALAR > >(P->copy()) : nullptr;
606:           auto term = _ID_(cm, Si, V - Si, std::move(Pcopy));
607:           if (!t) t = std::move(term);
608:           else t = std::make_unique< ASTmult< GUM_SCALAR > >(std::move(term), std::move(t));
609:         }
610:         NodeSet Vyx = V - (X + Y);
611:         if (Vyx.empty()) return t;
612:         std::vector< std::string > tosum;
613:         tosum.reserve(Vyx.size());
614:         for (auto v: Vyx)
615:           tosum.push_back(cm.nameFromId(v));
616:         return std::make_unique< ASTsum< GUM_SCALAR > >(tosum, std::move(t));
617:       }
618: 
619:       // Only one component:
620:       NodeSet S   = icomp.front();
621:       auto    cdg = _cDecomposition_(cm);
622: 
623:       // --- 5) Hedge check: if full graph is one c-component, not identifiable
624:       if (cdg.size() == 1) {
625:         NodeSet all = cdg.front();
626:         if (all.size() == V.size()) {
627:           // build names for message
628:           Set< std::string > Vn, Sn;
629:           for (auto v: V)
630:             Vn.insert(cm.nameFromId(v));
631:           for (auto s: S)
632:             Sn.insert(cm.nameFromId(s));
633:           auto msg = _hedgeExceptionMsg(cm, Y, X, V, S);
634:           GUM_ERROR(HedgeException, msg);
635:         }
636:       }

638:       // --- 6) If S is also a c-component in G: product of local conditionals over S
639:       {
640:         // test membership: S ∈ cdg ?
641:         bool sInCdg = false;
642:         for (const auto& comp: cdg) {
643:           if (comp == S) {
644:             sInCdg = true;
645:             break;
646:           }
647:         }
648: 
649:         if (sInCdg) {
650:           // P_new := Π_{v∈S in topo order} P(v | v_π) under current P (if provided),
651:           // otherwise P from the BN (chain rule)
652:           auto       order = _topoObserved_(cm);
653:           const DAG  dag   = cm.causalDAG();
654:           const auto id2n  = cm.id2name(/*includeLatentVariables=*/false);
655: 
656:           std::unique_ptr< ASTtree< GUM_SCALAR > > prod;
657: 
658:           // Make a name lookup for quick topo prefix
659:           std::unordered_map< NodeId, Size > pos;
660:           for (Size i = 0; i < order.size(); ++i)
661:             pos[order[i]] = i;
662: 
663:           // build in topo order filtered to S
664:           std::vector< NodeId > ordering;
665:           ordering.reserve(S.size());
666:           for (auto v: order)
667:             if (S.contains(v)) ordering.push_back(v);
668: 
669:           for (Size j = 0; j < ordering.size(); ++j) {
670:             auto                                     v = ordering[j];
671:             std::unique_ptr< ASTtree< GUM_SCALAR > > term;
672:             if (!P) {
673:               // from BN: P(v | predecessors) using chain rule prefix
674:               Size               k = pos[v];
675:               Set< std::string > condNames;
676:               for (Size i = 0; i < k; ++i)
677:                 condNames.insert(cm.nameFromId(order[i]));
678:               Set< std::string > lhs;
679:               lhs.insert(cm.nameFromId(v));
680:               if (condNames.empty()) term = std::make_unique< ASTjointProba< GUM_SCALAR > >(lhs);
681:               else
682:                 term = std::make_unique< ASTposteriorProba< GUM_SCALAR > >(dag,
683:                                                                            id2n,
684:                                                                            lhs,
685:                                                                            condNames);
686:             } else {
687:               // from accumulated P: factorize Q[S] by full-order prefix marginals
688:               Size                       k = pos[v];
689:               std::vector< std::string > prefixNames;
690:               prefixNames.reserve(k + 1);
691:               for (Size i = 0; i <= k; ++i)
692:                 prefixNames.push_back(cm.nameFromId(order[i]));
693: 
694:               // numerator = marginal of P on current prefix
695:               std::unique_ptr< ASTtree< GUM_SCALAR > > num(P->copy());
696:               std::vector< std::string >               sumNum;
697:               for (auto u: V) {
698:                 const auto& un = cm.nameFromId(u);
699:                 if (std::find(prefixNames.begin(), prefixNames.end(), un) == prefixNames.end()) {
700:                   sumNum.push_back(un);
701:                 }
702:               }
703:               if (!sumNum.empty()) {
704:                 num = std::make_unique< ASTsum< GUM_SCALAR > >(sumNum, std::move(num));
705:               }
706: 
707:               if (k == 0) {
708:                 Set< std::string > lhs;
709:                 lhs.insert(cm.nameFromId(v));
710:                 term = std::make_unique< ASTjointProba< GUM_SCALAR > >(lhs);
711: 
712:               } else {
713:                 // denominator = marginal of P on previous prefix
714:                 std::unique_ptr< ASTtree< GUM_SCALAR > > den(P->copy());
715:                 std::vector< std::string >               prevPrefix;
716:                 prevPrefix.reserve(k);
717:                 for (Size i = 0; i < k; ++i)
718:                   prevPrefix.push_back(cm.nameFromId(order[i]));
719:                 std::vector< std::string > sumDen;
720:                 for (auto u: V) {
721:                   const auto& un = cm.nameFromId(u);
722:                   if (std::find(prevPrefix.begin(), prevPrefix.end(), un) == prevPrefix.end()) {
723:                     sumDen.push_back(un);
724:                   }
725:                 }
726:                 if (!sumDen.empty()) {
727:                   den = std::make_unique< ASTsum< GUM_SCALAR > >(sumDen, std::move(den));
728:                 }
729:                 term = std::make_unique< ASTdiv< GUM_SCALAR > >(std::move(num), std::move(den));
730:               }
731:             }
732: 
733:             if (!prod) prod = std::move(term);
734:             else prod = std::make_unique< ASTmult< GUM_SCALAR > >(std::move(term), std::move(prod));
735:           }
736: 
737:           NodeSet Sy = S - Y;
738:           if (Sy.empty()) return prod;
739:           std::vector< std::string > tosum;
740:           tosum.reserve(Sy.size());
741:           for (auto v: Sy)
742:             tosum.push_back(cm.nameFromId(v));
743:           return std::make_unique< ASTsum< GUM_SCALAR > >(tosum, std::move(prod));

747:       // --- 7) Else: pick a c-component S' of G, build Q[S'] then recurse on G[S']
748:       {
749:         // choose the c-component of G that contains S (SP Step 7: S ⊆ S')
750:         NodeSet Spr;
751:         bool    found = false;
752:         for (const auto& comp: cdg) {
753:           if ((S - comp).empty()) {
754:             Spr   = comp;
755:             found = true;
756:             break;
757:           }
758:         }
759:         if (!found) {
760:           // Fallback should not happen; be conservative
761:           Spr = S;
762:         }
763: 
764:         auto       order = _topoObserved_(cm);
765:         const DAG  dag   = cm.causalDAG();
766:         const auto id2n  = cm.id2name(/*includeLatentVariables=*/false);
767: 
768:         std::unique_ptr< ASTtree< GUM_SCALAR > > prod;
769: 
770:         std::unordered_map< NodeId, Size > pos;
771:         for (Size i = 0; i < order.size(); ++i)
772:           pos[order[i]] = i;
773: 
774:         std::vector< NodeId > ordering;
775:         ordering.reserve(Spr.size());
776:         for (auto v: order)
777:           if (Spr.contains(v)) ordering.push_back(v);
778: 
779:         for (Size j = 0; j < ordering.size(); ++j) {
780:           auto                                     v = ordering[j];
781:           std::unique_ptr< ASTtree< GUM_SCALAR > > term;
782:           if (!P) {
783:             Size               k = pos[v];
784:             Set< std::string > condNames;
785:             for (Size i = 0; i < k; ++i)
786:               condNames.insert(cm.nameFromId(order[i]));
787:             Set< std::string > lhs;
788:             lhs.insert(cm.nameFromId(v));
789:             if (condNames.empty()) term = std::make_unique< ASTjointProba< GUM_SCALAR > >(lhs);
790:             else
791:               term = std::make_unique< ASTposteriorProba< GUM_SCALAR > >(dag, id2n, lhs, condNames);
792:           } else {
793:             // from accumulated P: factorize Q[Spr] by full-order prefix marginals
794:             Size                       k = pos[v];
795:             std::vector< std::string > prefixNames;
796:             prefixNames.reserve(k + 1);
797:             for (Size i = 0; i <= k; ++i)
798:               prefixNames.push_back(cm.nameFromId(order[i]));
799: 
800:             // numerator = marginal of P on current prefix
801:             std::unique_ptr< ASTtree< GUM_SCALAR > > num(P->copy());
802:             std::vector< std::string >               sumNum;
803:             for (auto u: V) {
804:               const auto& un = cm.nameFromId(u);
805:               if (std::find(prefixNames.begin(), prefixNames.end(), un) == prefixNames.end()) {
806:                 sumNum.push_back(un);
807:               }
808:             }
809:             if (!sumNum.empty()) {
810:               num = std::make_unique< ASTsum< GUM_SCALAR > >(sumNum, std::move(num));
811:             }
812: 
813:             if (k == 0) {
814:               Set< std::string > lhs;
815:               lhs.insert(cm.nameFromId(v));
816:               term = std::make_unique< ASTjointProba< GUM_SCALAR > >(lhs);
817: 
818:             } else {
819:               // denominator = marginal of P on previous prefix
820:               std::unique_ptr< ASTtree< GUM_SCALAR > > den(P->copy());
821:               std::vector< std::string >               prevPrefix;
822:               prevPrefix.reserve(k);
823:               for (Size i = 0; i < k; ++i)
824:                 prevPrefix.push_back(cm.nameFromId(order[i]));
825:               std::vector< std::string > sumDen;
826:               for (auto u: V) {
827:                 const auto& un = cm.nameFromId(u);
828:                 if (std::find(prevPrefix.begin(), prevPrefix.end(), un) == prevPrefix.end()) {
829:                   sumDen.push_back(un);
830:                 }
831:               }
832:               if (!sumDen.empty()) {
833:                 den = std::make_unique< ASTsum< GUM_SCALAR > >(sumDen, std::move(den));
834:               }
835:               term = std::make_unique< ASTdiv< GUM_SCALAR > >(std::move(num), std::move(den));
836:             }
837:           }
838: 
839:           if (!prod) prod = std::move(term);
840:           else prod = std::make_unique< ASTmult< GUM_SCALAR > >(std::move(term), std::move(prod));
841:         }
842: 
843:         auto    sub  = cm.inducedCausalSubModel(cm, Spr);
844:         NodeSet Yspr = Y * Spr;   // <— important
845:         NodeSet Xspr = X * Spr;
846: 
847:         if (Yspr.empty()) {
848:           GUM_ERROR(OperationNotAllowed,
849:                     "Internal error in ID step 7: chosen C-component is disjoint from Y.");
850:         }
851: 
852:         return _ID_(sub, Yspr, Xspr, std::move(prod));

