297:   template < GUM_Numeric GUM_SCALAR >
298:   CausalModel< GUM_SCALAR >
299:       CausalModel< GUM_SCALAR >::inducedCausalSubModel(const CausalModel< GUM_SCALAR >& cm,
300:                                                        NodeSet subset) const {
301:     // If caller gave an empty subset, use "all observed" nodes
302:     if (subset.empty()) {
303:       for (auto n: cm._observedDAG_.nodes())
304:         subset.insert(n);
305:     }
306: 
307:     // Keep only OBSERVED nodes (drop latents explicitly)
308:     NodeSet nodes = subset;
309:     for (auto L: cm.latentVariablesIds())
310:       nodes.erase(L);
311: 
312:     // --- Build a named DAG restricted to `nodes` (structure only: no BN, no CPTs).
313:     // NodeIds are preserved so that NodeSets expressed in `cm`'s id space (Y, X, ...) stay valid
314:     // in the induced sub-model.
315:     DAG sub;
316:     for (auto n: nodes) {
317:       sub.addNodeWithId(n);
318:       sub.setName(n, cm.nameFromId(n));
319:     }
320: 
321:     // add arcs among the kept observed nodes (from the *causal* DAG)
322:     const auto causalDag = cm.causalDAG();
323:     for (const auto& a: causalDag.arcs()) {
324:       const NodeId x = a.tail();
325:       const NodeId y = a.head();
326:       if (nodes.contains(x) && nodes.contains(y)) { sub.addArc(x, y); }
327:     }
328: 
329:     // --- Rebuild latent descriptor restricted to kept nodes
330:     LatentDescriptorVector latentDesc;
331:     for (auto L: cm.latentVariablesIds()) {
332:       std::vector< NodeId > mapped_children;
333:       mapped_children.reserve(4);
334: 
335:       // intersect latent children with kept observed nodes
336:       for (auto c: cm.children(L)) {
337:         if (nodes.contains(c)) mapped_children.push_back(c);
338:       }
339: 
340:       // keep the latent ONLY if it still has at least 2 children
341:       if (mapped_children.size() >= 2) {
342:         latentDesc.emplace_back(cm.nameFromId(L), std::move(mapped_children));
343:       }
344:     }
345: 
346:     // assumeNonSpurious=true : pyagrum uses True here (do not remove arcs among children)
347:     return CausalModel< GUM_SCALAR >(sub, latentDesc, /*assumeNonSpurious=*/true);
348:   }
